// Pusher pack — Sokoban: push boxes onto goals; irreversibility IS the puzzle,
// so unbounded undo/redo and dead-square detection are first-class. Parses the
// standard XSB level format (inherits thousands of community levels). Its own
// artifact, not in webgpu.js.

export interface XY { x: number; y: number }
export type Dir = 'up' | 'down' | 'left' | 'right';

const DELTA: Record<Dir, XY> = { up: { x: 0, y: -1 }, down: { x: 0, y: 1 }, left: { x: -1, y: 0 }, right: { x: 1, y: 0 } };

export interface MoveResult {
  moved: boolean;
  pushed: { from: XY; to: XY } | null;
  ontoDeadSquare: boolean;
  solved: boolean;
}

export interface PusherConfig {
  /** XSB rows: `#` wall · space/`-` floor · `@` player · `+` player-on-goal ·
   * `$` box · `*` box-on-goal · `.` goal. */
  level: string[];
}

export function createPusher(cfg: PusherConfig): Pusher {
  return new Pusher(cfg);
}

interface Snapshot { player: XY; boxes: string }

export class Pusher {
  readonly cols: number;
  readonly rows: number;
  moves = 0;
  pushes = 0;

  private wall: boolean[];
  private goal: boolean[];
  private box: boolean[];
  private player: XY;
  private dead: boolean[];
  private history: { move: MoveDelta }[] = [];
  private future: { move: MoveDelta }[] = [];

  constructor(cfg: PusherConfig) {
    const rows = cfg.level;
    this.rows = rows.length;
    this.cols = Math.max(...rows.map((r) => r.length));
    const n = this.cols * this.rows;
    this.wall = new Array(n).fill(false);
    this.goal = new Array(n).fill(false);
    this.box = new Array(n).fill(false);
    this.player = { x: 0, y: 0 };
    for (let y = 0; y < this.rows; y++) {
      for (let x = 0; x < this.cols; x++) {
        const ch = rows[y][x] ?? ' ';
        const i = this.idx(x, y);
        if (ch === '#') this.wall[i] = true;
        if (ch === '.' || ch === '*' || ch === '+') this.goal[i] = true;
        if (ch === '$' || ch === '*') this.box[i] = true;
        if (ch === '@' || ch === '+') this.player = { x, y };
      }
    }
    this.dead = this.computeDeadSquares();
  }

  private idx(x: number, y: number): number { return y * this.cols + x; }
  private inBounds(x: number, y: number): boolean { return x >= 0 && y >= 0 && x < this.cols && y < this.rows; }

  isWall(x: number, y: number): boolean { return this.inBounds(x, y) ? this.wall[this.idx(x, y)] : true; }
  isGoal(x: number, y: number): boolean { return this.inBounds(x, y) && this.goal[this.idx(x, y)]; }
  isBox(x: number, y: number): boolean { return this.inBounds(x, y) && this.box[this.idx(x, y)]; }
  isDead(x: number, y: number): boolean { return this.inBounds(x, y) && this.dead[this.idx(x, y)]; }
  get playerPos(): XY { return { ...this.player }; }

  get metrics(): { moves: number; pushes: number } { return { moves: this.moves, pushes: this.pushes }; }

  /** Solved when every box sits on a goal. */
  get solved(): boolean {
    for (let i = 0; i < this.box.length; i++) if (this.box[i] && !this.goal[i]) return false;
    // also require all goals covered (equivalent when #boxes == #goals)
    for (let i = 0; i < this.goal.length; i++) if (this.goal[i] && !this.box[i]) return false;
    return true;
  }

  /** Move the player in `dir`, pushing a single box if one is ahead. */
  move(dir: Dir): MoveResult {
    const d = DELTA[dir];
    const nx = this.player.x + d.x; const ny = this.player.y + d.y;
    if (this.isWall(nx, ny)) return { moved: false, pushed: null, ontoDeadSquare: false, solved: this.solved };
    let pushed: { from: XY; to: XY } | null = null;
    let ontoDead = false;
    if (this.isBox(nx, ny)) {
      const bx = nx + d.x; const by = ny + d.y;
      if (this.isWall(bx, by) || this.isBox(bx, by)) return { moved: false, pushed: null, ontoDeadSquare: false, solved: this.solved };
      this.box[this.idx(nx, ny)] = false;
      this.box[this.idx(bx, by)] = true;
      pushed = { from: { x: nx, y: ny }, to: { x: bx, y: by } };
      ontoDead = this.dead[this.idx(bx, by)] && !this.goal[this.idx(bx, by)];
      this.pushes++;
    }
    const from = { ...this.player };
    this.player = { x: nx, y: ny };
    this.moves++;
    const delta: MoveDelta = { dir, from, pushed };
    this.history.push({ move: delta });
    this.future = [];
    return { moved: true, pushed, ontoDeadSquare: ontoDead, solved: this.solved };
  }

  /** Undo the last move (pulling a pushed box back). */
  undo(): boolean {
    const last = this.history.pop();
    if (!last) return false;
    const { dir, from, pushed } = last.move;
    const d = DELTA[dir];
    if (pushed) {
      // box moved from `pushed.from` to `pushed.to`; pull it back
      this.box[this.idx(pushed.to.x, pushed.to.y)] = false;
      this.box[this.idx(pushed.from.x, pushed.from.y)] = true;
      this.pushes--;
    }
    this.player = { ...from };
    this.moves--;
    this.future.push(last);
    return true;
  }

  /** Redo an undone move. */
  redo(): boolean {
    const next = this.future.pop();
    if (!next) return false;
    this.history.push(next);
    const { dir, pushed } = next.move;
    const d = DELTA[dir];
    if (pushed) {
      this.box[this.idx(pushed.from.x, pushed.from.y)] = false;
      this.box[this.idx(pushed.to.x, pushed.to.y)] = true;
      this.pushes++;
    }
    this.player = { x: this.player.x + d.x, y: this.player.y + d.y };
    this.moves++;
    return true;
  }

  /** Dead squares: cells from which no box can ever reach a goal. Precomputed by
   * reverse-pulling boxes from every goal; anything unreached is dead. */
  private computeDeadSquares(): boolean[] {
    const n = this.cols * this.rows;
    const live = new Array(n).fill(false);
    const queue: XY[] = [];
    for (let i = 0; i < n; i++) if (this.goal[i]) { live[i] = true; queue.push({ x: i % this.cols, y: (i / this.cols) | 0 }); }
    // A box at cell c can be pulled to cell c+d if the player can stand at c+2d.
    while (queue.length) {
      const c = queue.shift()!;
      for (const dir of ['up', 'down', 'left', 'right'] as Dir[]) {
        const d = DELTA[dir];
        const bx = c.x - d.x; const by = c.y - d.y;      // box came from here
        const px = c.x - 2 * d.x; const py = c.y - 2 * d.y; // player stood here to pull
        if (!this.inBounds(bx, by) || this.wall[this.idx(bx, by)]) continue;
        if (!this.inBounds(px, py) || this.wall[this.idx(px, py)]) continue;
        const bi = this.idx(bx, by);
        if (!live[bi]) { live[bi] = true; queue.push({ x: bx, y: by }); }
      }
    }
    const dead = new Array(n).fill(false);
    for (let i = 0; i < n; i++) if (!this.wall[i] && !live[i]) dead[i] = true;
    return dead;
  }

  /** Is the box at (x,y) frozen (immovable on both axes and not on a goal)? */
  isFrozen(x: number, y: number): boolean {
    if (!this.isBox(x, y)) return false;
    return this.frozenAxis(x, y, 'h', new Set()) && this.frozenAxis(x, y, 'v', new Set());
  }

  private frozenAxis(x: number, y: number, axis: 'h' | 'v', visiting: Set<number>): boolean {
    const i = this.idx(x, y);
    if (visiting.has(i)) return true;
    visiting.add(i);
    const [a, b] = axis === 'h' ? [DELTA.left, DELTA.right] : [DELTA.up, DELTA.down];
    const blocked = (d: XY) => {
      const nx = x + d.x; const ny = y + d.y;
      if (this.isWall(nx, ny)) return true;
      if (this.dead[this.idx(nx, ny)] && !this.goal[this.idx(nx, ny)]) {
        // a wall of dead squares on this side counts as blocked
      }
      if (this.isBox(nx, ny)) return this.frozenAxis(nx, ny, axis === 'h' ? 'v' : 'h', visiting);
      return false;
    };
    return blocked(a) || blocked(b);
  }

  /** Optional BFS solver for small levels (hints). Returns a move sequence or null. */
  solve(maxNodes = 200000): Dir[] | null {
    const start = this.snapshot();
    const startKey = this.key(start);
    if (this.solvedFrom(start)) return [];
    const seen = new Set<string>([startKey]);
    const queue: { snap: Snapshot; path: Dir[] }[] = [{ snap: start, path: [] }];
    let nodes = 0;
    while (queue.length && nodes++ < maxNodes) {
      const { snap, path } = queue.shift()!;
      for (const dir of ['up', 'down', 'left', 'right'] as Dir[]) {
        const next = this.applyTo(snap, dir);
        if (!next) continue;
        const k = this.key(next.snap);
        if (seen.has(k)) continue;
        // prune moves that push a box onto a dead square
        if (next.pushedToDead) continue;
        if (this.solvedFrom(next.snap)) return [...path, dir];
        seen.add(k);
        queue.push({ snap: next.snap, path: [...path, dir] });
      }
    }
    return null;
  }

  private snapshot(): Snapshot {
    let boxes = '';
    for (let i = 0; i < this.box.length; i++) boxes += this.box[i] ? '1' : '0';
    return { player: { ...this.player }, boxes };
  }
  private key(s: Snapshot): string { return `${s.player.x},${s.player.y}|${s.boxes}`; }
  private solvedFrom(s: Snapshot): boolean {
    for (let i = 0; i < this.goal.length; i++) if (this.goal[i] && s.boxes[i] !== '1') return false;
    return true;
  }
  private applyTo(s: Snapshot, dir: Dir): { snap: Snapshot; pushedToDead: boolean } | null {
    const d = DELTA[dir];
    const nx = s.player.x + d.x; const ny = s.player.y + d.y;
    if (this.isWall(nx, ny)) return null;
    const boxes = s.boxes.split('');
    let pushedToDead = false;
    if (boxes[this.idx(nx, ny)] === '1') {
      const bx = nx + d.x; const by = ny + d.y;
      if (this.isWall(bx, by) || boxes[this.idx(bx, by)] === '1') return null;
      boxes[this.idx(nx, ny)] = '0';
      boxes[this.idx(bx, by)] = '1';
      pushedToDead = this.dead[this.idx(bx, by)] && !this.goal[this.idx(bx, by)];
    }
    return { snap: { player: { x: nx, y: ny }, boxes: boxes.join('') }, pushedToDead };
  }

  debugGrid(): string {
    const rows: string[] = [];
    for (let y = 0; y < this.rows; y++) {
      let r = '';
      for (let x = 0; x < this.cols; x++) {
        const i = this.idx(x, y);
        const isPlayer = this.player.x === x && this.player.y === y;
        r += this.wall[i] ? '#' : isPlayer ? (this.goal[i] ? '+' : '@') : this.box[i] ? (this.goal[i] ? '*' : '$') : this.goal[i] ? '.' : ' ';
      }
      rows.push(r);
    }
    return rows.join('\n');
  }
}

interface MoveDelta { dir: Dir; from: XY; pushed: { from: XY; to: XY } | null }

// ===========================================================================
// createHistory — the shared undo/redo service (used by pusher, gridsim's
// Snakebird, and any turn-based component).
// ===========================================================================

export interface History<T> {
  do(action: T): void;
  undo(): T | null;
  redo(): T | null;
  canUndo(): boolean;
  canRedo(): boolean;
  clear(): void;
  readonly length: number;
}

/** Unbounded undo/redo over caller-supplied apply/revert. */
export function createHistory<T>(hooks: { apply: (a: T) => void; revert: (a: T) => void }): History<T> {
  const past: T[] = [];
  const future: T[] = [];
  return {
    do(action: T) { hooks.apply(action); past.push(action); future.length = 0; },
    undo() { const a = past.pop(); if (a === undefined) return null; hooks.revert(a); future.push(a); return a; },
    redo() { const a = future.pop(); if (a === undefined) return null; hooks.apply(a); past.push(a); return a; },
    canUndo() { return past.length > 0; },
    canRedo() { return future.length > 0; },
    clear() { past.length = 0; future.length = 0; },
    get length() { return past.length; },
  };
}
